package com.bjjj.todo;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.View;import android.widget.*;import android.graphics.Color;import android.util.TypedValue;import org.json.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
public class TodoWidget extends AppWidgetProvider {
 static final String COMPLETE="com.bjjj.todo.COMPLETE",PAGE="com.bjjj.todo.PAGE";
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,id);Reminder.schedule(c);}
 public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle b){update(c,id);}
 public void onReceive(Context c,Intent i){super.onReceive(c,i);try{if(COMPLETE.equals(i.getAction())){Store.done(c,i.getStringExtra("task"),true);Store.changed(c);}else if(PAGE.equals(i.getAction())){int id=i.getIntExtra("widget",0),delta=i.getIntExtra("delta",0);var p=c.getSharedPreferences("widgets",0);p.edit().putInt("page"+id,Math.max(0,p.getInt("page"+id,0)+delta)).apply();update(c,id);}}catch(Exception e){Toast.makeText(c,"保存失败，请打开应用检查",Toast.LENGTH_LONG).show();}}
 public void onDeleted(Context c,int[] ids){var editor=c.getSharedPreferences("widgets",0).edit();for(int id:ids)editor.remove("page"+id);editor.apply();}
 public static void updateAll(Context c){for(int id:AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,TodoWidget.class)))update(c,id);}
 static PendingIntent activity(Context c,boolean add){return PendingIntent.getActivity(c,add?2:1,new Intent(c,MainActivity.class).putExtra("create",add),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static List<JSONObject> items(Context c,int id)throws Exception{List<JSONObject> open=Store.open(Store.read(c)),rows=new ArrayList<>();long end=LocalDate.now().plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();List<JSONObject> today=new ArrayList<>();for(JSONObject t:open)if(Store.due(t)<end)today.add(t);int height=AppWidgetManager.getInstance(c).getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,400);if(height>=300){rows.add(new JSONObject().put("heading","今日待办 · "+today.size()+"（含逾期）"));rows.addAll(today.subList(0,Math.min(5,today.size())));if(today.isEmpty())rows.add(new JSONObject().put("heading","今天没有截止事项，按自己的节奏来。"));if(today.size()>5)rows.add(new JSONObject().put("heading","其余今日事项可在下方全部未完成中查看"));}rows.add(new JSONObject().put("heading","全部未完成 · "+open.size()));int pages=Math.max(1,(open.size()+39)/40),page=Math.min(pages-1,c.getSharedPreferences("widgets",0).getInt("page"+id,0));rows.addAll(open.subList(Math.min(open.size(),page*40),Math.min(open.size(),(page+1)*40)));if(open.isEmpty())rows.add(new JSONObject().put("heading","给下一件事留个位置，点击＋新建。"));return rows;}
 static RemoteViews row(Context c,JSONObject t,int index){if(t.has("heading")){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_heading);r.setTextViewText(R.id.heading,t.optString("heading"));return r;}RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_row);r.setTextViewText(R.id.title,t.optString("title"));long due=Store.due(t);String time=due==Long.MAX_VALUE?"无截止时间":(due<System.currentTimeMillis()?"已逾期 · ":"")+Instant.ofEpochMilli(due).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("M/d HH:mm"));r.setTextViewText(R.id.meta,Store.priority(t)+" · "+Store.category(t)+" · "+time);r.setTextColor(R.id.meta,Color.parseColor(switch(t.optString("priority")){case "high"->"#efb5bd";case "low"->"#bad8ed";default->"#e6d39b";}));r.setOnClickFillInIntent(R.id.check,new Intent().putExtra("task",t.optString("id")));r.setContentDescription(R.id.check,"完成 "+t.optString("title"));return r;}
 public static void update(Context c,int id){try{JSONObject root=Store.read(c);int count=Store.open(root).size(),pages=Math.max(1,(count+39)/40),page=Math.min(pages-1,c.getSharedPreferences("widgets",0).getInt("page"+id,0));RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);v.setInt(R.id.backdrop,"setImageAlpha",root.getJSONObject("settings").optInt("opacity",85)*255/100);v.setOnClickPendingIntent(R.id.brand,activity(c,false));v.setOnClickPendingIntent(R.id.add,activity(c,true));v.setTextViewText(R.id.footer,pages>1?"第 "+(page+1)+" / "+pages+" 页 · 未完成每天都在":"未完成，每天都在 · 点方框完成");for(int view:new int[]{R.id.prev,R.id.next}){int delta=view==R.id.prev?-1:1;v.setViewVisibility(view,pages>1?View.VISIBLE:View.GONE);Intent intent=new Intent(c,TodoWidget.class).setAction(PAGE).setData(android.net.Uri.parse("bjjj://page/"+id+"/"+delta)).putExtra("widget",id).putExtra("delta",delta);v.setOnClickPendingIntent(view,PendingIntent.getBroadcast(c,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}Intent complete=new Intent(c,TodoWidget.class).setAction(COMPLETE);v.setPendingIntentTemplate(R.id.tasks,PendingIntent.getBroadcast(c,id,complete,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0)));
 if(Build.VERSION.SDK_INT>=31){RemoteViews.RemoteCollectionItems.Builder b=new RemoteViews.RemoteCollectionItems.Builder().setViewTypeCount(2).setHasStableIds(false);List<JSONObject> rows=items(c,id);for(int n=0;n<rows.size();n++)b.addItem(n,row(c,rows.get(n),n));v.setRemoteAdapter(R.id.tasks,b.build());}else{Intent service=new Intent(c,WidgetService.class).putExtra("widget",id).setData(android.net.Uri.parse("bjjj://list/"+id));v.setRemoteAdapter(R.id.tasks,service);}AppWidgetManager.getInstance(c).updateAppWidget(id,v);if(Build.VERSION.SDK_INT<31)AppWidgetManager.getInstance(c).notifyAppWidgetViewDataChanged(id,R.id.tasks);
 }catch(Exception e){android.util.Log.e("bjjj","Widget update failed",e);}}
}
